@cli.command()
def query(
    document_ids: list[str] = typer.Argument(..., help="文档 ID 列表"),
    dataset_id: Optional[str] = typer.Option(None, help="数据集 ID"),
    output_format: str = typer.Option("text", help="输出格式: text/json"),
):
    """查询文档内容。"""
    async def _query():
        # 使用默认 dataset_id
        ds_id = dataset_id or settings.dify.default_dataset_id
        if not ds_id:
            typer.echo("❌ 请指定 dataset_id 或在配置中设置默认值", err=True)
            raise typer.Exit(1)

        service = RetrievalService()
        result = await service.retrieve_documents(
            dataset_id=ds_id,
            document_ids=document_ids,
        )

        if output_format == "json":
            import json
            typer.echo(json.dumps(
                [doc.model_dump() for doc in result.documents],
                ensure_ascii=False,
                indent=2,
            ))
        else:
            typer.echo(f"查询到 {result.total} 条文档:\n")
            if result.formatted_content:
                typer.echo(result.formatted_content)

    asyncio.run(_query())

