@cli.command()
def status(
    document_id: str = typer.Argument(..., help="文档 ID"),
    action: str = typer.Argument(..., help="操作: enable/disable/archive"),
    dataset_id: Optional[str] = typer.Option(None, help="数据集 ID"),
):
    """变更文档状态。"""
    from dify_milvus_rag.models import DocumentAction

    async def _status():
        async with DocumentService.create() as service:
            result = await service.change_document_status(
                document_id=document_id,
                action=DocumentAction(action),
                dataset_id=dataset_id,
            )

            if result.code == 200:
                typer.echo(f"✅ 操作成功: {result.message}")
            else:
                typer.echo(f"❌ 操作失败: {result.message}", err=True)

    asyncio.run(_status())

@cli.command()
def batch_upload(
    directory: Path = typer.Argument(..., help="文件目录路径"),
    pattern: str = typer.Option("*.pdf", help="文件匹配模式"),
    dataset_id: Optional[str] = typer.Option(None, help="目标数据集 ID"),
):
    """批量上传目录中的文件。"""
    async def _batch_upload():
        files = list(directory.glob(pattern))

        if not files:
            typer.echo(f"未找到匹配的文件: {pattern}")
            return

        typer.echo(f"找到 {len(files)} 个文件，开始上传...")

        async with DocumentService.create() as service:
            results = await service.batch_upload_and_index(
                file_paths=files,
                dataset_id=dataset_id,
            )

            success_count = sum(1 for r in results if r.status == "success")
            typer.echo(f"\n✅ 上传完成: {success_count}/{len(files)} 成功")

            for file, result in zip(files, results):
                if result.status == "success":
                    typer.echo(f"   ✅ {file.name}: {result.document_id}")
                else:
                    typer.echo(f"   ❌ {file.name}: {result.message}")

    if not directory.is_dir():
        typer.echo(f"❌ 目录不存在: {directory}", err=True)
        raise typer.Exit(1)

    asyncio.run(_batch_upload())
